import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    private ThreadPoolTaskScheduler bad() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler(); //bad
        return scheduler;
    }

    private final ThreadPoolTaskScheduler field = new ThreadPoolTaskScheduler(); //bad
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    private ThreadPoolTaskScheduler good() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(5);
        return scheduler;
    }
}
